const payload = $input.first().json.body ?? $input.first().json;

const allowedChannels = ['whatsapp', 'email', 'instagram', 'facebook', 'linkedin', 'webchat', 'other'];
const missing = ['channel', 'external_message_id', 'text'].filter((field) => !payload[field] || String(payload[field]).trim() === '');

if (missing.length > 0) return [{ json: { httpStatus: 400, response: { ok: false, error: 'Datos de entrada incompletos', missing, expected: { channel: 'whatsapp | email | instagram | facebook | linkedin | webchat | other', external_message_id: 'ID único del mensaje en el canal', text: 'Contenido del mensaje' } } } }];
if (!allowedChannels.includes(payload.channel)) return [{ json: { httpStatus: 400, response: { ok: false, error: 'Canal no soportado', allowed_channels: allowedChannels } } }];

const store = $getWorkflowStaticData('global');
store.identityMap = store.identityMap || {};
store.openOpportunity = store.openOpportunity || {};
store.processedMessages = store.processedMessages || {};

const closedStages = ['closed_won', 'closed_lost'];
const senderValue = payload.sender_id || payload.sender || null;
const identityKey = senderValue ? payload.channel + ':' + senderValue : null;
const eventId = payload.event_id || 'evt-' + payload.external_message_id;
const receivedAt = payload.received_at || new Date().toISOString();
const processedKey = payload.channel + ':' + payload.external_message_id;

const processed = store.processedMessages[processedKey];
if (processed) return [{ json: { httpStatus: 200, response: { ok: true, duplicate: true, event_id: processed.event_id, contact_id: processed.contact_id, opportunity_id: processed.opportunity_id, message: 'Mensaje ya procesado; no se creó una nueva oportunidad.' } } }];

let contactId = payload.contact_id || null;
let contactStatus = payload.contact_id ? 'confirmed' : 'candidate';
if (!contactId && identityKey && store.identityMap[identityKey]) { contactId = store.identityMap[identityKey]; contactStatus = 'confirmed'; }
if (!contactId) contactId = 'contact-' + payload.channel + '-' + payload.external_message_id;
if (identityKey) store.identityMap[identityKey] = contactId;

let opportunityId = payload.opportunity_id || null;
let isNewOpportunity = false;
if (!opportunityId) {
  const existing = store.openOpportunity[contactId];
  if (existing && !closedStages.includes(existing.stage)) opportunityId = existing.opportunity_id;
  else { opportunityId = 'opp-' + payload.channel + '-' + payload.external_message_id; isNewOpportunity = true; }
}
if (isNewOpportunity || !store.openOpportunity[contactId]) store.openOpportunity[contactId] = { opportunity_id: opportunityId, stage: 'new' };

store.processedMessages[processedKey] = { event_id: eventId, contact_id: contactId, opportunity_id: opportunityId };

const identity = senderValue ? { channel: payload.channel, value: String(senderValue), verified: Boolean(payload.contact_id), verified_at: payload.contact_id ? receivedAt : null } : null;
const contact = { contact_id: contactId, company_id: payload.company_id || null, identities: identity ? [identity] : [], status: contactStatus, source_of_match: payload.contact_id ? 'payload.contact_id' : identityKey && store.identityMap[identityKey] === contactId ? 'channel:sender_id' : null };
const outboundMessageDraft = senderValue ? { opportunity_id: opportunityId, channel: payload.channel, recipient: String(senderValue), text: 'Hola, recibimos tu consulta. Un asesor te responderá a la brevedad.', reply_to_external_message_id: payload.external_message_id, idempotency_key: 'out-' + eventId, status: 'pending_channel_connection', created_at: receivedAt } : null;

return [{ json: { httpStatus: 201, response: { ok: true, duplicate: false, event: { event_id: eventId, event_type: 'message_received', occurred_at: receivedAt, contact_id: contactId, opportunity_id: opportunityId, channel: payload.channel, source: 'n8n:copiloto-ingreso-prospecto-mvp', payload: { external_message_id: payload.external_message_id, text: payload.text }, schema_version: 'v1' }, contact, opportunity_is_new: isNewOpportunity, opportunity: { opportunity_id: opportunityId, contact_id: contactId, stage: store.openOpportunity[contactId]?.stage || 'new', owner_id: payload.owner_id || payload.owner || null, next_step: senderValue ? 'Analizar la conversación y preparar la siguiente acción comercial' : 'Resolver identidad antes de preparar contacto de salida', next_step_at_or_condition: 'inmediatamente tras la validación comercial', last_event_id: eventId, summary: 'Prospecto ingresado desde ' + payload.channel + '.' }, outbound_message_draft: outboundMessageDraft } } }];
